// Generated by Cypress Author on 2026-11-04 for IMP-03.07. Real preproduction traffic only.
import type { Session } from '@supabase/supabase-js';
import {
  attemptResponseSchema,
  runExecutionResponseSchema,
} from '@alunza/contracts';

type Fixture = {
  baseUrl: string;
  webOrigin: string;
  supabaseHost: string;
  actorId: string;
  actorSession: Session;
  activityId: string;
  assignmentId: string;
  exerciseVersionId: string;
  successfulCode: string;
  failingCode: string;
  privateSentinels: string[];
};
type Observation = {
  id: string;
  executionId?: string;
  attemptId?: string;
  previousAttemptId?: string;
  diagnosis?: 'FAILED_TEST' | 'SUCCESS';
  clientRequests?: number;
};
const record = (observation: Observation) =>
  cy.task('remoteSandbox:record', observation, { log: false });
function writeCode(code: string) {
  cy.get('[data-cy="student-code"]', { log: false })
    .should('not.have.attr', 'readonly')
    .click({ log: false });
  cy.get('[data-cy="student-code"]', { log: false })
    .should('not.have.attr', 'readonly')
    .clear({ log: false });
  cy.get('[data-cy="student-code"]', { log: false })
    .should('have.value', '')
    .type(code, { parseSpecialCharSequences: false, delay: 0, log: false });
  cy.get('[data-cy="student-code"]', { log: false }).should('have.value', code);
}
function submitCode() {
  cy.get('[data-cy="submit-code"]', { log: false })
    .should('be.enabled')
    .click({ log: false });
  cy.get('[role="dialog"]', { log: false }).should(
    'contain.text',
    'Confirmar envío de intento',
  );
  cy.get('[data-cy="confirm-submit"]', { log: false })
    .should('be.enabled')
    .click({ log: false });
}
function assertPrivateContentAbsent(value: unknown, fixture: Fixture) {
  const text = typeof value === 'string' ? value : JSON.stringify(value);
  if (fixture.privateSentinels.some((sentinel) => text.includes(sentinel)))
    throw new Error('PRIVATE_CONTENT_LEAK');
}

describe('IMP-03.07 · Práctica web con Sandbox real', () => {
  afterEach(() => {
    cy.clearAllLocalStorage({ log: false });
  });

  it('SBX-BROWSER-01 · Ejecutar, enviar y reintentar → conserva resultados y progreso al recargar', () => {
    cy.env(
      [
        'remoteSandboxFixture',
        'browserDeadline',
        'clientRequestBudget',
        'approvedReleaseId',
      ],
      {
        log: false,
      },
    ).then((values) => {
      const fixture = values.remoteSandboxFixture as Fixture;
      const approvedReleaseId = values.approvedReleaseId as string;
      if (!/^[a-f0-9]{40}$/.test(approvedReleaseId))
        throw new Error('BROWSER_APPROVED_RELEASE_REQUIRED');
      const deadline = Number(values.browserDeadline),
        requestBudget = Number(values.clientRequestBudget);
      const route = `${fixture.baseUrl}/api/v1/activities/${fixture.activityId}/exercises/${fixture.assignmentId}`;
      let clientRequests = 0,
        posts = 0,
        firstAttemptId = '',
        firstExecutionId = '',
        successfulAttemptId = '';
      const keys = new Set<string>();
      const persistedAttempts = new Set<string>();
      let helpRequests = 0;
      // Logging suppression only; all requests and responses continue unchanged.
      cy.intercept({ resourceType: /xhr|fetch/ }, { log: false });
      cy.intercept(
        { url: `${fixture.baseUrl}/**`, middleware: true },
        (request) => {
          if (++clientRequests > requestBudget || Date.now() >= deadline)
            throw new Error('BROWSER_REQUEST_BUDGET');
          const pathname = new URL(request.url).pathname;
          const help = pathname.match(
            /^\/api\/v1\/attempts\/([^/]+)\/(feedback|feedback-requests)$/,
          );
          if (help) {
            helpRequests++;
            if (!help[1] || !persistedAttempts.has(help[1]))
              throw new Error('HELP_BEFORE_PERSISTED_ATTEMPT');
            if (request.method !== 'GET')
              throw new Error('AI_INVOCATION_OUTSIDE_BROWSER_STAGE');
          }
          const execution =
            request.method === 'POST' &&
            [route + '/executions', route + '/attempts'].includes(request.url);
          if (execution && ++posts > 4)
            throw new Error('BROWSER_CREATION_BUDGET');
          request.on('before:response', (response) => {
            const release = Object.entries(response.headers).find(
              ([name]) => name.toLowerCase() === 'x-release-id',
            )?.[1];
            if (release !== approvedReleaseId)
              throw new Error('BROWSER_RELEASE_MISMATCH');
            assertPrivateContentAbsent(response.body, fixture);
            if (
              (request.method === 'POST' &&
                request.url === `${route}/attempts` &&
                response.statusCode === 201) ||
              (request.method === 'GET' &&
                /^\/api\/v1\/attempts\/[^/]+$/.test(pathname) &&
                response.statusCode === 200)
            ) {
              persistedAttempts.add(
                attemptResponseSchema.parse(response.body).data.attemptId,
              );
            }
          });
        },
      );
      cy.intercept('POST', `${route}/executions`).as('run');
      cy.intercept('POST', `${route}/attempts`).as('submit');
      cy.intercept('GET', `${route}/attempts*`).as('history');
      cy.intercept('GET', `${fixture.baseUrl}/api/v1/attempts/*/feedback?*`).as(
        'helpHistory',
      );
      cy.visit(
        `/actividades/${fixture.activityId}/ejercicios/${fixture.assignmentId}`,
        {
          log: false,
          onBeforeLoad(window) {
            window.localStorage.setItem(
              `alunza.auth.${fixture.supabaseHost}`,
              JSON.stringify(fixture.actorSession),
            );
          },
        },
      );
      cy.wait('@history', { log: false }).then(({ response }) => {
        expect(response?.statusCode, 'historial real disponible').to.equal(200);
        expect(
          response?.body.data,
          'fixture sin intentos anteriores',
        ).to.have.length(0);
      });
      cy.get('[data-cy="activity-progress"]', { log: false }).should(
        'contain.text',
        'Sin intentos',
      );
      cy.get('[data-cy="attempt-help"]', { log: false }).should('not.exist');
      writeCode(fixture.failingCode);
      cy.get('[data-cy="run-code"]', { log: false })
        .should('be.enabled')
        .click({ log: false });
      cy.wait('@run', { responseTimeout: 45000, log: false }).then(
        ({ response }) => {
          expect(response?.statusCode).to.equal(201);
          const result = runExecutionResponseSchema.parse(response?.body).data;
          expect(result.technicalResult.diagnosisCode).to.equal('FAILED_TEST');
          expect(result.technicalResult.infrastructureStatus).to.equal('OK');
          firstExecutionId = result.executionId;
        },
      );
      cy.get('[data-cy="run-diagnosis"]', { log: false }).should(
        'contain.text',
        'FAILED_TEST',
      );
      cy.get('[data-cy="attempt-history-row"]', { log: false }).should(
        'have.length',
        0,
      );
      cy.get('[data-cy="activity-progress"]', { log: false }).should(
        'contain.text',
        'Sin intentos',
      );
      cy.then(() =>
        record({
          id: 'browser-run-failed',
          executionId: firstExecutionId,
          diagnosis: 'FAILED_TEST',
        }),
      );
      cy.get('[data-cy="attempt-help"]', { log: false }).should('not.exist');

      cy.get('[data-cy="submit-code"]', { log: false })
        .should('be.enabled')
        .click({ log: false });
      cy.get('[data-cy="cancel-submit"]', { log: false }).click({ log: false });
      cy.get('[role="dialog"]', { log: false }).should('not.exist');
      cy.then(() => {
        expect(posts, 'cancelación sin admisión adicional').to.equal(1);
        expect(
          helpRequests,
          'ninguna ayuda antes de persistir un intento',
        ).to.equal(0);
      });
      record({ id: 'browser-submit-cancelled' });

      submitCode();
      cy.wait('@submit', { responseTimeout: 45000, log: false }).then(
        ({ request, response }) => {
          expect(response?.statusCode).to.equal(201);
          const result = attemptResponseSchema.parse(response?.body).data;
          expect(result.technicalResult.diagnosisCode).to.equal('FAILED_TEST');
          expect(result.technicalResult.allRequiredPassed).to.equal(false);
          expect(result.technicalResult.infrastructureStatus).to.equal('OK');
          expect(result.code).to.equal(fixture.failingCode);
          expect(result.attemptNumber).to.equal(1);
          firstAttemptId = result.attemptId;
          keys.add(String(request.headers['idempotency-key']));
          return record({
            id: 'browser-submit-failed',
            executionId: result.executionId,
            attemptId: result.attemptId,
            diagnosis: 'FAILED_TEST',
          });
        },
      );
      cy.get('[data-cy="attempt-diagnosis"]', { log: false }).should(
        'contain.text',
        'FAILED_TEST',
      );
      cy.get('[data-cy="attempt-history-row"]', { log: false }).should(
        'have.length',
        1,
      );
      cy.wait('@helpHistory', { log: false }).then(({ request, response }) => {
        expect(new URL(request.url).pathname).to.equal(
          `/api/v1/attempts/${firstAttemptId}/feedback`,
        );
        expect(response?.statusCode).to.equal(200);
        expect(response?.body.data.capabilities.canExplain).to.equal(true);
        expect(response?.body.data.capabilities.pendingRequest).to.equal(null);
      });
      cy.get('[data-cy="attempt-help"]', { log: false }).should(
        'contain.text',
        'Ayuda para el intento #1',
      );
      cy.get('[data-cy="request-feedback"]', { log: false }).should(
        'be.enabled',
      );
      cy.get('[data-cy="activity-progress"]', { log: false }).should(
        'contain.text',
        'completados: 0/1',
      );

      writeCode(fixture.successfulCode);
      submitCode();
      cy.wait('@submit', { responseTimeout: 45000, log: false }).then(
        ({ request, response }) => {
          expect(response?.statusCode).to.equal(201);
          const result = attemptResponseSchema.parse(response?.body).data;
          expect(result.technicalResult.diagnosisCode).to.equal('SUCCESS');
          expect(result.technicalResult.allRequiredPassed).to.equal(true);
          expect(result.technicalResult.hiddenChecksPassed).to.equal(true);
          expect(result.attemptNumber).to.equal(2);
          expect(result.attemptId).not.to.equal(firstAttemptId);
          expect(keys.has(String(request.headers['idempotency-key']))).to.equal(
            false,
          );
          keys.add(String(request.headers['idempotency-key']));
          successfulAttemptId = result.attemptId;
          return record({
            id: 'browser-submit-success',
            executionId: result.executionId,
            attemptId: result.attemptId,
            diagnosis: 'SUCCESS',
          });
        },
      );
      cy.get('[data-cy="attempt-history-row"]', { log: false }).should(
        'have.length',
        2,
      );
      cy.get('[data-cy="activity-progress"]', { log: false }).should(
        'contain.text',
        'completados: 1/1',
      );
      cy.reload({ log: false });
      cy.get('[data-cy="student-code"]', { log: false }).should(
        'have.value',
        fixture.successfulCode,
      );
      cy.get('[data-cy="attempt-history-row"]', { log: false }).should(
        'have.length',
        2,
      );
      cy.get('[data-cy="activity-progress"]', { log: false }).should(
        'contain.text',
        'completados: 1/1',
      );
      cy.contains('[data-cy="attempt-history-row"]', 'Intento #1', {
        log: false,
      })
        .find('[data-cy="show-attempt"]', { log: false })
        .click({ log: false });
      cy.get('[data-cy="attempt-detail"]', { log: false }).should(
        'contain.text',
        'Intento #1 guardado',
      );
      cy.get('[data-cy="attempt-detail"] [data-cy="attempt-help"]', {
        log: false,
      }).should('contain.text', 'Ayuda para el intento #1');
      cy.get('[data-cy="attempt-detail"] [data-cy="request-feedback"]', {
        log: false,
      }).should('be.enabled');
      cy.get('[data-cy="attempt-detail"] summary', { log: false }).click({
        log: false,
      });
      cy.get('[data-cy="attempt-source"]', { log: false }).should(
        'have.text',
        fixture.failingCode,
      );
      record({ id: 'browser-history-reload' });

      cy.get('[data-cy="copy-attempt"]', { log: false }).click({ log: false });
      cy.get('[data-cy="confirm-copy"]', { log: false }).click({ log: false });
      cy.get('[data-cy="student-code"]', { log: false }).should(
        'have.value',
        fixture.failingCode,
      );
      writeCode(fixture.successfulCode);
      submitCode();
      cy.wait('@submit', { responseTimeout: 45000, log: false }).then(
        ({ request, response }) => {
          expect(response?.statusCode).to.equal(201);
          const result = attemptResponseSchema.parse(response?.body).data;
          expect(result.previousAttemptId).to.equal(firstAttemptId);
          expect(request.body.previousAttemptId).to.equal(firstAttemptId);
          expect(result.attemptId).not.to.be.oneOf([
            firstAttemptId,
            successfulAttemptId,
          ]);
          expect(result.attemptNumber).to.equal(3);
          expect(result.technicalResult.diagnosisCode).to.equal('SUCCESS');
          expect(result.technicalResult.allRequiredPassed).to.equal(true);
          expect(keys.has(String(request.headers['idempotency-key']))).to.equal(
            false,
          );
          keys.add(String(request.headers['idempotency-key']));
          return record({
            id: 'browser-intentional-retry',
            executionId: result.executionId,
            attemptId: result.attemptId,
            previousAttemptId: firstAttemptId,
            diagnosis: 'SUCCESS',
          });
        },
      );
      cy.get('[data-cy="attempt-history-row"]', { log: false }).should(
        'have.length',
        3,
      );
      cy.get('[data-cy="activity-progress"]', { log: false }).should(
        'contain.text',
        'completados: 1/1',
      );
      cy.get('body', { log: false }).then((body) => {
        assertPrivateContentAbsent(body.text(), fixture);
      });
      cy.then(() => {
        expect(posts, 'una práctica y tres envíos reales').to.equal(4);
        expect(keys.size, 'tres admisiones diferentes').to.equal(3);
        return record({ id: 'browser-hidden-redaction', clientRequests });
      });
    });
  });
});
